<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\{Settings,MailAutomation};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,Password,RateLimiter};
use Illuminate\Support\Str;
class AuthController extends Controller {
 public function page(Request $r,string $mode='login'){$ownerStep=false;if($mode==='owner'&&$r->query('restart'))$r->session()->forget('owner_challenge');if($mode==='owner'){$c=$r->session()->get('owner_challenge');if($c&&$c['until']>=now()->timestamp&&$c['attempts']<5){$mode='verify';$ownerStep=true;$ownerTotp=!empty($c['totp']);}}return response()->view('auth',['ownerTotp'=>$ownerTotp??false,'ownerStep'=>$ownerStep,'mode'=>$mode,'token'=>$r->route('token'),'email'=>$r->query('email',''),'action'=>($mode==='owner'||$ownerStep)?'/'.$r->path():'/'.$mode])->header('X-Robots-Tag','noindex, nofollow')->cookie('cvtara-device',$r->cookie('cvtara-device')?:bin2hex(random_bytes(32)),525600,'/',null,$r->isSecure(),true,false,'Lax');}
 public function register(Request $r){$r->merge(['email'=>strtolower(trim((string)$r->input('email')))]);$v=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users','password'=>'required|string|min:8|max:200|confirmed','experienceLevel'=>'required|in:fresher,experienced','profession'=>'required|string|max:120','category'=>'required|string|max:100','terms'=>'accepted'],['password.confirmed'=>'The two passwords do not match. Type the same password in both boxes.','password.min'=>'Use at least 8 characters for your password.','email.unique'=>'An account with this email already exists. Sign in instead, or use Forgot password.','email.email'=>'Enter a valid email address, like you@example.com.','terms.accepted'=>'Please accept the terms to create your account.','name.required'=>'Enter your full name.','profession.required'=>'Tell us the role you are aiming for.']);$u=DB::transaction(function()use($v,$r){$u=User::create(['name'=>$v['name'],'email'=>strtolower($v['email']),'password'=>Hash::make($v['password'])]);$dev=\App\Services\Wallet::device($r);$u->forceFill(['referral_code'=>\App\Services\Referrals::makeCode($v['name']),'device_hash'=>$dev,'last_device_hash'=>$dev])->save();$code=$r->session()->get('referral.code')??$r->cookie('cvtara_ref');$at=$r->session()->get('referral.at')??($code?time():null);$ref=$code&&$at&&now()->subDays(30)->timestamp<$at?\App\Services\Referrals::owner((string)$code):null;if($ref&&$ref->blocked)$ref=null;if($ref&&$ref->id!==$u->id)$u->forceFill(['referred_by'=>$ref->id,'referral_attached_at'=>now()])->save();DB::table('profiles')->insert(['owner_id'=>$u->id,'name'=>$v['name'],'experience_level'=>$v['experienceLevel'],'profession'=>$v['profession'],'category'=>$v['category'],'onboarding_done'=>true,'marketing_consent'=>$r->boolean('marketing'),'created_at'=>now(),'updated_at'=>now()]);\App\Services\Attribution::stamp($u,$r);\App\Services\Attribution::lock($u,$r);return $u;});Auth::login($u);$r->session()->regenerate();MailAutomation::queue($u,'profile_created','signup');Settings::audit($u->id,'registered');$next=(string)$r->input('next','');if(\App\Services\EmailVerification::required($u)){\App\Services\EmailVerification::send($u);$safe=$next!==''&&str_starts_with($next,'/')&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!str_starts_with($next,'/admin');return redirect('/verify-email'.($safe?'?next='.urlencode($next):''));}if($next!==''&&str_starts_with($next,'/')&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!preg_match('/[\\x00-\\x1f\\x7f]|%0[0-9a-f]|%2f|%5c/i',$next)&&!str_starts_with($next,'/admin'))return redirect($next);return redirect('/workspace.html');}
 public function ownerLogin(Request $r){if($r->has('code'))return $this->ownerCode($r);$v=$r->validate(['email'=>'required|email|max:190','password'=>'required|string|max:200']);$email=strtolower($v['email']);$key='owner-login:'.sha1($email.'|'.$r->ip());$any='owner-login-any:'.sha1($email);
 // Per address and IP (5 tries / 15 min) and per address from anywhere (20 tries / hour), so a spread-out guessing run is also stopped.
 if(RateLimiter::tooManyAttempts($key,5)||RateLimiter::tooManyAttempts($any,20))return back()->withErrors(['email'=>'Too many attempts. Try again in 15 minutes.']);
 $u=User::where('email',$email)->where('blocked',false)->first();if($u&&!\App\Services\Access::isStaff($u))$u=null;
 if(!$u||!Hash::check($v['password'],$u->password)){RateLimiter::hit($key,900);RateLimiter::hit($any,3600);return back()->withErrors(['email'=>'Email or password is incorrect.']);}
 RateLimiter::clear($key);
 // 3.37.0: an authenticator app, when switched on, replaces the emailed code (works even if email is down).
 if(\App\Services\Totp::enabled($u)&&config('app.owner_login_code')&&!config('app.preview')){$r->session()->put('owner_challenge',['user'=>$u->id,'totp'=>true,'until'=>now()->timestamp+900,'attempts'=>0]);Settings::audit($u->id,'owner_totp_asked',$r->path());return redirect('/'.$r->path());}
 if(!self::ownerCodeRequired())return $this->ownerSignIn($r,$u,false);
 $send='owner-code-send:'.$u->id;if(RateLimiter::tooManyAttempts($send,5))return back()->withErrors(['email'=>'Several sign-in codes were sent already. Use the latest one, or wait 15 minutes.']);RateLimiter::hit($send,900);
 $code=(string)random_int(100000,999999);$r->session()->put('owner_challenge',['user'=>$u->id,'hash'=>Hash::make($code),'until'=>now()->timestamp+900,'attempts'=>0]);
 $id=(string)Str::uuid();DB::table('mail_outbox')->insert(['id'=>$id,'dedupe'=>(string)Str::uuid(),'owner_id'=>$u->id,'trigger'=>'security_verification','recipient'=>$u->email,'subject'=>'Your CVTara owner sign-in code','body'=>"# Owner sign-in code\n[preheader: Enter this code to open the owner console. It works for 15 minutes.]\nSomeone (hopefully you) entered the correct owner password for CVTara. Enter this code to finish signing in:\n\n[code: $code]\n\nThe code works for 15 minutes. If this was not you, change the owner password now: someone knows it.",'due_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);
 if(!MailAutomation::sendNow($id))\App\Services\ErrorLog::record('warning','security','The owner sign-in code email could not be sent at once; it stays queued and is retried by the mail cron.',null,null,$u->id);
 Settings::audit($u->id,'owner_code_sent',$r->path());
 return redirect('/'.$r->path());}
 private function ownerCode(Request $r){$c=$r->session()->get('owner_challenge');$v=$r->validate(['code'=>'required|digits:6']);
 if(!$c||$c['until']<now()->timestamp||$c['attempts']>=5){$r->session()->forget('owner_challenge');return redirect('/'.$r->path())->withErrors(['email'=>'That code expired or had too many tries. Sign in again to get a new code.']);}
 $c['attempts']++;$r->session()->put('owner_challenge',$c);
 if(!empty($c['totp'])){$tu=User::whereKey($c['user'])->where('blocked',false)->first();if(!$tu||!\App\Services\Totp::verify($tu,$v['code']))return back()->withErrors(['code'=>'That code is not right. Use the newest code in your authenticator app.']);}
 elseif(!Hash::check($v['code'],$c['hash']))return back()->withErrors(['code'=>'That code is not right. Check the latest email and try again.']);
 $r->session()->forget('owner_challenge');$u=User::whereKey($c['user'])->where('blocked',false)->first();if($u&&!\App\Services\Access::isStaff($u))$u=null;
 if(!$u)return redirect('/'.$r->path())->withErrors(['email'=>'This account cannot open the owner console.']);
 return $this->ownerSignIn($r,$u,true);}
 private function ownerSignIn(Request $r,User $u,bool $coded){Auth::login($u,false);$r->session()->regenerate();
 // Password plus emailed code is the same proof the console asks for before sensitive saves, so it unlocks them for the usual hour.
 if($coded){$r->session()->put('sensitive_until',now()->timestamp+3600);$r->session()->put('sensitive_user',$u->id);}
 Settings::audit($u->id,'owner_signed_in',$r->path());\App\Services\Audit::record($u,'security:console_sign_in',(string)$u->id,null,['with'=>$coded?'code':'password'],'',200,$r);return redirect('/admin.html');}
 public static function ownerCodeRequired():bool{return config('app.owner_login_code')&&!config('app.preview')&&(bool)(Settings::get('integrations')['email']??false);}
 public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required|string']);$key='login:'.sha1(strtolower($v['email']).'|'.$r->ip());if(RateLimiter::tooManyAttempts($key,5))return back()->withErrors(['email'=>'Too many attempts. Try again in 15 minutes.']);if(!config('app.preview')&&($cu=User::where('email',strtolower($v['email']))->first())&&\App\Services\Access::isStaff($cu)){RateLimiter::hit($key,900);return back()->withErrors(['email'=>'Email or password is incorrect.']);}if(!Auth::attempt(['email'=>strtolower($v['email']),'password'=>$v['password'],'blocked'=>false],false)){RateLimiter::hit($key,900);return back()->withErrors(['email'=>'Email or password is incorrect.']);}RateLimiter::clear($key);$r->session()->regenerate();$r->user()?->forceFill(['last_device_hash'=>\App\Services\Wallet::device($r)])->save();$next=(string)$r->input('next','');$safe=$next!==''&&$next[0]==='/'&&!str_starts_with($next,'//')&&!str_contains($next,'\\')&&!preg_match('/[\\x00-\\x1f\\x7f]|%0[0-9a-f]|%2f|%5c/i',$next);if($safe&&(!str_starts_with($next,'/admin')||$r->user()->is_admin))return redirect($next);return redirect($r->user()->is_admin?'/admin.html':'/workspace.html');}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}
 public function forgot(Request $r){$r->validate(['email'=>'required|email']);$u=User::where('email',strtolower($r->email))->first();if($u){$token=Password::createToken($u);MailAutomation::queue($u,'password_reset',hash('sha256',$token),['reset_url'=>rtrim((string)config('app.url'),'/').'/reset-password/'.$token.'?email='.urlencode($u->email)],true);}return back()->with('status','If that account exists, a reset link has been queued for delivery.');}
 public function reset(Request $r){$r->validate(['token'=>'required','email'=>'required|email','password'=>'required|string|min:8|max:200|confirmed'],['password.confirmed'=>'The two passwords do not match. Type the same password in both boxes.','password.min'=>'Use at least 8 characters for your password.']);$status=Password::reset($r->only('email','password','password_confirmation','token'),function(User $u,string $p){$u->forceFill(['password'=>Hash::make($p),'remember_token'=>Str::random(60)])->save();DB::table('sessions')->where('user_id',$u->id)->delete();});return $status===Password::PASSWORD_RESET?redirect('/login')->with('status','Password updated. Sign in with your new password.'):back()->withErrors(['email'=>'This reset link is invalid or expired.']);}
}
